UPDATE "recipes"
SET "status" = CASE
  WHEN "status" = 'pending' THEN 'suggested'
  WHEN "status" IN ('analysing', 'ready', 'scheduled') THEN 'approved'
  ELSE "status"
END
WHERE "status" IN ('pending', 'analysing', 'ready', 'scheduled');
